constexpr int M=17408,N=2*M,K=5120,GK=32,G=K/GK,ROWS=8,RB=M/ROWS,WARPS=16,THREADS=512,RPC=WARPS*ROWS;
constexpr int CORR_CAP=M,CORR_WARPS=8,CORR_THREADS=CORR_WARPS*32,DOWN_N=5120,DOWN_GROUPS=M/32;
constexpr std::size_t PACKED=(std::size_t)RB*G*32*sizeof(uint2),SCALE=(std::size_t)RB*G*ROWS*sizeof(std::uint32_t),AQ=(std::size_t)4*K,AS=(std::size_t)4*G*sizeof(__half);
constexpr std::size_t CORR_CODES=(std::size_t)2*CORR_CAP*K,CORR_SCALES=(std::size_t)2*CORR_CAP*G*sizeof(std::uint16_t);

struct State{const void*source=nullptr;uint2*packed=nullptr;std::uint32_t*scales=nullptr;std::int8_t*aq=nullptr;__half*as=nullptr;std::int32_t*corr_rows=nullptr;std::int8_t*corr_codes=nullptr;std::uint16_t*corr_scales=nullptr;__nv_bfloat16*exact_values=nullptr;};State& state(){static State s;return s;}
int mode(){static int value=[](){const char*e=std::getenv("NINFER_SM75_MTP_W4_MODE");int v=e?std::atoi(e):0;return v<0?0:(v>3?3:v);}();return value;}
int correction_count(){static int value=[](){const char*e=std::getenv("NINFER_SM75_MTP_W4_CORRECT");int v=e?std::atoi(e):0;return v<0?0:(v>CORR_CAP?CORR_CAP:v);}();return value;}
int rank_mode(){static int value=[](){const char*e=std::getenv("NINFER_SM75_MTP_W4_RANK");int v=e?std::atoi(e):0;return v<0?0:(v>2?2:v);}();return value;}
__device__ __forceinline__ std::uint32_t expand4(std::uint16_t p){std::uint32_t x=p,n=__byte_perm(x&0x0f0fu,(x>>4)&0x0f0fu,0x5140);return n|((n&0x08080808u)*30u);}
__global__ void transform(const std::int8_t*codes,const std::uint16_t*src_sc,uint2*out,std::uint32_t*out_sc,float*row_error){
 __shared__ __align__(16) std::uint8_t gc[ROWS][16],uc[ROWS][16];__shared__ std::uint16_t gs[ROWS],us[ROWS];int lane=(int)threadIdx.x&31,row8=lane>>2,lid=lane&3,rb=(int)blockIdx.x,row=rb*ROWS+row8;float ge=0.f,gnorm=0.f,ue=0.f,unorm=0.f;
 for(int g=0;g<G;++g){const auto*gp=codes+(std::int64_t)row*K+g*GK+lid*8;const auto*up=codes+(std::int64_t)(row+M)*K+g*GK+lid*8;int gm=0,um=0;
#pragma unroll
  for(int i=0;i<8;++i){gm=max(gm,abs((int)gp[i]));um=max(um,abs((int)up[i]));}gm=max(gm,__shfl_xor_sync(__activemask(),gm,1,4));gm=max(gm,__shfl_xor_sync(__activemask(),gm,2,4));um=max(um,__shfl_xor_sync(__activemask(),um,1,4));um=max(um,__shfl_xor_sync(__activemask(),um,2,4));float ga=gm?(float)gm/7.f:0.f,ua=um?(float)um/7.f:0.f;
#pragma unroll
  for(int it=0;it<2;++it){float gn=0.f,gd=0.f,un=0.f,ud=0.f;
#pragma unroll
   for(int i=0;i<8;++i){int gq=ga?__float2int_rn((float)gp[i]/ga):0,uq=ua?__float2int_rn((float)up[i]/ua):0;gq=max(-7,min(7,gq));uq=max(-7,min(7,uq));gn+=(float)gp[i]*(float)gq;gd+=(float)(gq*gq);un+=(float)up[i]*(float)uq;ud+=(float)(uq*uq);}gn+=__shfl_xor_sync(__activemask(),gn,1,4);gn+=__shfl_xor_sync(__activemask(),gn,2,4);gd+=__shfl_xor_sync(__activemask(),gd,1,4);gd+=__shfl_xor_sync(__activemask(),gd,2,4);un+=__shfl_xor_sync(__activemask(),un,1,4);un+=__shfl_xor_sync(__activemask(),un,2,4);ud+=__shfl_xor_sync(__activemask(),ud,1,4);ud+=__shfl_xor_sync(__activemask(),ud,2,4);ga=gd>0.f?gn/gd:0.f;ua=ud>0.f?un/ud:0.f;}
  float gss=__half2float(__ushort_as_half(src_sc[(std::int64_t)row*G+g])),uss=__half2float(__ushort_as_half(src_sc[(std::int64_t)(row+M)*G+g]));if(lid==0){gs[row8]=__half_as_ushort(__float2half_rn(gss*ga));us[row8]=__half_as_ushort(__float2half_rn(uss*ua));}
#pragma unroll
  for(int i=0;i<4;++i){int q0=ga?__float2int_rn((float)gp[2*i]/ga):0,q1=ga?__float2int_rn((float)gp[2*i+1]/ga):0,r0=ua?__float2int_rn((float)up[2*i]/ua):0,r1=ua?__float2int_rn((float)up[2*i+1]/ua):0;q0=max(-7,min(7,q0));q1=max(-7,min(7,q1));r0=max(-7,min(7,r0));r1=max(-7,min(7,r1));gc[row8][lid*4+i]=(std::uint8_t)((q0&15)|((q1&15)<<4));uc[row8][lid*4+i]=(std::uint8_t)((r0&15)|((r1&15)<<4));float gt0=(float)gp[2*i]*gss,gt1=(float)gp[2*i+1]*gss,ga0=(float)q0*ga*gss,ga1=(float)q1*ga*gss;float ut0=(float)up[2*i]*uss,ut1=(float)up[2*i+1]*uss,ua0=(float)r0*ua*uss,ua1=(float)r1*ua*uss;ge=__fmaf_rn(gt0-ga0,gt0-ga0,ge);ge=__fmaf_rn(gt1-ga1,gt1-ga1,ge);gnorm=__fmaf_rn(gt0,gt0,gnorm);gnorm=__fmaf_rn(gt1,gt1,gnorm);ue=__fmaf_rn(ut0-ua0,ut0-ua0,ue);ue=__fmaf_rn(ut1-ua1,ut1-ua1,ue);unorm=__fmaf_rn(ut0,ut0,unorm);unorm=__fmaf_rn(ut1,ut1,unorm);}
  __syncwarp();std::uint32_t gate=(std::uint32_t)*reinterpret_cast<std::uint16_t*>(&gc[row8][lid*2])|((std::uint32_t)*reinterpret_cast<std::uint16_t*>(&gc[row8][lid*2+8])<<16);std::uint32_t upv=(std::uint32_t)*reinterpret_cast<std::uint16_t*>(&uc[row8][lid*2])|((std::uint32_t)*reinterpret_cast<std::uint16_t*>(&uc[row8][lid*2+8])<<16);out[((std::int64_t)rb*G+g)*32+lane]=make_uint2(gate,upv);if(lane<ROWS)out_sc[((std::int64_t)rb*G+g)*ROWS+lane]=(std::uint32_t)gs[lane]|((std::uint32_t)us[lane]<<16);__syncwarp();}
 ge+=__shfl_xor_sync(__activemask(),ge,1,4);ge+=__shfl_xor_sync(__activemask(),ge,2,4);gnorm+=__shfl_xor_sync(__activemask(),gnorm,1,4);gnorm+=__shfl_xor_sync(__activemask(),gnorm,2,4);ue+=__shfl_xor_sync(__activemask(),ue,1,4);ue+=__shfl_xor_sync(__activemask(),ue,2,4);unorm+=__shfl_xor_sync(__activemask(),unorm,1,4);unorm+=__shfl_xor_sync(__activemask(),unorm,2,4);if(lid==0)row_error[row]=fmaxf(gnorm>0.f?ge/gnorm:0.f,unorm>0.f?ue/unorm:0.f);
}
__global__ void down_column_norm(const std::int8_t*codes,const std::uint16_t*scales,float*out){int col=(int)blockIdx.x,g=col/32;float sum=0.f;for(int row=(int)threadIdx.x;row<DOWN_N;row+=blockDim.x){float sc=__half2float(__ushort_as_half(scales[(std::int64_t)row*DOWN_GROUPS+g]));float v=(float)codes[(std::int64_t)row*M+col]*sc;sum=__fmaf_rn(v,v,sum);}__shared__ float warp_sums[8];float total=block_reduce_sum<256>(sum,warp_sums);if(threadIdx.x==0)out[col]=total;}
__global__ void gather_corrections(const std::int32_t*rows,const std::int8_t*src_codes,const std::uint16_t*src_scales,std::int8_t*dst_codes,std::uint16_t*dst_scales){int c=(int)blockIdx.x,row=rows[c];for(int d=(int)threadIdx.x;d<K;d+=blockDim.x){dst_codes[(std::int64_t)c*K+d]=src_codes[(std::int64_t)row*K+d];dst_codes[(std::int64_t)(CORR_CAP+c)*K+d]=src_codes[(std::int64_t)(M+row)*K+d];}for(int g=(int)threadIdx.x;g<G;g+=blockDim.x){dst_scales[(std::int64_t)c*G+g]=src_scales[(std::int64_t)row*G+g];dst_scales[(std::int64_t)(CORR_CAP+c)*G+g]=src_scales[(std::int64_t)(M+row)*G+g];}}
__global__ void exact_correct_t1(const __nv_bfloat16*x,const std::int32_t*rows,const std::int8_t*codes,const std::uint16_t*scales,int count,__nv_bfloat16*out){int warp=(int)threadIdx.x>>5,lane=(int)threadIdx.x&31,c=(int)blockIdx.x*CORR_WARPS+warp;if(c>=count)return;int row=rows[c];const auto*gate=codes+(std::int64_t)row*K;const auto*up=codes+(std::int64_t)(M+row)*K;const auto*gs=scales+(std::int64_t)row*G;const auto*us=scales+(std::int64_t)(M+row)*G;float ga=0.f,ua=0.f;constexpr int VALUES=8,PHASE_VALUES=32*VALUES,GROUPS_PER_PHASE=PHASE_VALUES/GK,PHASES=K/PHASE_VALUES;
#pragma unroll
 for(int phase=0;phase<PHASES;++phase){unsigned gsb=0,usb=0;if(lane<GROUPS_PER_PHASE){gsb=gs[phase*GROUPS_PER_PHASE+lane];usb=us[phase*GROUPS_PER_PHASE+lane];}gsb=__shfl_sync(0xffffffffu,gsb,lane>>2);usb=__shfl_sync(0xffffffffu,usb,lane>>2);float gsf=__half2float(__ushort_as_half(gsb)),usf=__half2float(__ushort_as_half(usb));int k=phase*PHASE_VALUES+lane*VALUES;uint2 gp=load_vec<uint2>(gate+k),upv=load_vec<uint2>(up+k);uint4 xv=load_vec<uint4>(x+k);float2 xf[4]={bf16x2_bits_to_float2(xv.x),bf16x2_bits_to_float2(xv.y),bf16x2_bits_to_float2(xv.z),bf16x2_bits_to_float2(xv.w)};
#pragma unroll
  for(int word=0;word<2;++word){std::uint32_t gw=(&gp.x)[word],uw=(&upv.x)[word];
#pragma unroll
   for(int byte=0;byte<4;++byte){int shift=byte*8;float a=(byte&1)?xf[word*2+(byte>>1)].y:xf[word*2+(byte>>1)].x;ga=fmaf((float)(std::int8_t)(gw>>shift)*gsf,a,ga);ua=fmaf((float)(std::int8_t)(uw>>shift)*usf,a,ua);}}}
 ga=warp_reduce_sum(ga);ua=warp_reduce_sum(ua);if(lane==0)out[row]=__float2bfloat16_rn(silu(ga)*ua);}

struct CorrectionRows {
 static constexpr int kOutputRowsPerCta=16;
 const std::int32_t* rows; int count;
 __device__ __forceinline__ int weight_row(int output_row0,int local_row) const {int compact=output_row0+local_row;if(compact<count)return rows[compact];if(compact<2*count)return M+rows[compact-count];return 0;}
};
__global__ void apply_exact_corrections(const __nv_bfloat16* projected,const std::int32_t*rows,int count,__nv_bfloat16*out){int c=(int)blockIdx.x*blockDim.x+threadIdx.x;if(c<count){float g=__bfloat162float(projected[c]),u=__bfloat162float(projected[CORR_CAP+c]);out[rows[c]]=__float2bfloat16_rn(silu(g)*u);}}
template<int T> __global__ void quant(const __nv_bfloat16*x,std::int8_t*q,__half*s){int warp=(int)threadIdx.x>>5,lane=(int)threadIdx.x&31,u=(int)blockIdx.x*8+warp;if(u>=T*G)return;int t=u/G,g=u-t*G,d=g*GK+lane;float v=__bfloat162float(x[(std::int64_t)t*K+d]),m=fabsf(v);for(int o=16;o;o>>=1)m=fmaxf(m,__shfl_xor_sync(__activemask(),m,o));float sc=m?m/127.f:0.f,iv=sc?1.f/sc:0.f;int a=__float2int_rn(v*iv);a=max(-127,min(127,a));q[(std::int64_t)t*K+d]=(std::int8_t)a;if(lane==0)s[t*G+g]=__float2half_rn(sc);}
template<int T> __launch_bounds__(THREADS) __global__ void swiglu(const uint2*w,const std::uint32_t*ws,const std::int8_t*aq,const __half*as,__nv_bfloat16*out){int warp=(int)threadIdx.x>>5,lane=(int)threadIdx.x&31,rb=(int)blockIdx.x*WARPS+warp,rowbase=rb*ROWS,gid=lane>>2,lid=lane&3;float fg0=0.f,fg1=0.f,fu0=0.f,fu1=0.f;uint2 p=w[((std::int64_t)rb*G)*32+lane];
#pragma unroll 1
 for(int g=0;g<G;++g){uint2 pn{};if(g+1<G)pn=w[((std::int64_t)rb*G+g+1)*32+lane];int c0=0,c1=0,c2=0,c3=0,t=lane>>2,q=lane&3;unsigned b0=0,b1=0;if(t<T){const auto*ab=reinterpret_cast<const std::uint32_t*>(aq+(std::int64_t)t*K+g*GK);b0=ab[q];b1=ab[4+q];}mma_s8(c0,c1,c2,c3,expand4((std::uint16_t)p.x),expand4((std::uint16_t)p.y),expand4((std::uint16_t)(p.x>>16)),expand4((std::uint16_t)(p.y>>16)),b0,b1);std::uint32_t sp=0;if(lid==0)sp=ws[((std::int64_t)rb*G+g)*ROWS+gid];sp=__shfl_sync(__activemask(),sp,gid*4);float gs=__half2float(__ushort_as_half((std::uint16_t)sp)),us=__half2float(__ushort_as_half((std::uint16_t)(sp>>16)));int t0=2*lid,t1=t0+1;float s0=t0<T?__half2float(as[t0*G+g]):0.f,s1=t1<T?__half2float(as[t1*G+g]):0.f;fg0=__fmaf_rn((float)c0,gs*s0,fg0);fg1=__fmaf_rn((float)c1,gs*s1,fg1);fu0=__fmaf_rn((float)c2,us*s0,fu0);fu1=__fmaf_rn((float)c3,us*s1,fu1);p=pn;}
 int t0=2*lid,t1=t0+1,row=rowbase+gid;if(t0<T)out[(std::int64_t)t0*M+row]=__float2bfloat16_rn((fg0/(1.f+expf(-fg0)))*fu0);if(t1<T)out[(std::int64_t)t1*M+row]=__float2bfloat16_rn((fg1/(1.f+expf(-fg1)))*fu1);}
template<int T> void launch(const Tensor&x,Tensor&out,cudaStream_t stream){auto&s=state();quant<T><<<(T*G+7)/8,256,0,stream>>>((const __nv_bfloat16*)x.data,s.aq,s.as);swiglu<T><<<M/RPC,THREADS,0,stream>>>(s.packed,s.scales,s.aq,s.as,(__nv_bfloat16*)out.data);if constexpr(T==1){int count=correction_count();if(count>0){using Geometry=W8LinearGeometry<CORR_CAP,K>;using Schedule=typename W8LinearSmallTProductionSchedule<W8MtpGateUpProjectionGeometry,1>::Type;W8ContiguousOutput gate_out{s.exact_values,CORR_CAP},up_out{s.exact_values+CORR_CAP,CORR_CAP};int blocks=(count+15)/16;w8_small_t_mma_kernel<Geometry,1,Schedule><<<blocks,Schedule::kThreads,0,stream>>>((const __nv_bfloat16*)x.data,(const std::uint8_t*)s.corr_codes,(const std::uint8_t*)s.corr_scales,gate_out);w8_small_t_mma_kernel<Geometry,1,Schedule><<<blocks,Schedule::kThreads,0,stream>>>((const __nv_bfloat16*)x.data,(const std::uint8_t*)(s.corr_codes+(std::int64_t)CORR_CAP*K),(const std::uint8_t*)(s.corr_scales+(std::int64_t)CORR_CAP*G),up_out);apply_exact_corrections<<<(count+255)/256,256,0,stream>>>(s.exact_values,s.corr_rows,count,(__nv_bfloat16*)out.data);}}CUDA_CHECK(cudaGetLastError());}
}
std::size_t w8_mtp_gateup_b2_sm75_reservation_bytes() noexcept{if(mode()==0)return 0;return PACKED+SCALE+AQ+AS+(correction_count()>0?(std::size_t)CORR_CAP*sizeof(std::int32_t)+CORR_CODES+CORR_SCALES+(std::size_t)2*CORR_CAP*sizeof(__nv_bfloat16):0);}
void w8_mtp_gateup_b2_sm75_prepare(const Weight&w,const Weight&down,cudaStream_t stream){if(w.qtype!=QType::W8G32_F16S||w.n!=N||w.k!=K||!w.qdata||!w.scales||down.qtype!=QType::W8G32_F16S||down.n!=DOWN_N||down.k!=M||!down.qdata||!down.scales)throw std::invalid_argument("SM75 MTP W4/A8 gate/up preparation requires exact W8 geometry");if(mode()==0)return;auto&s=state();if(s.source==w.qdata)return;CUDA_CHECK(cudaMalloc(&s.packed,PACKED));CUDA_CHECK(cudaMalloc(&s.scales,SCALE));CUDA_CHECK(cudaMalloc(&s.aq,AQ));CUDA_CHECK(cudaMalloc(&s.as,AS));float*errors=nullptr;CUDA_CHECK(cudaMalloc(&errors,(std::size_t)M*sizeof(float)));transform<<<RB,32,0,stream>>>((const std::int8_t*)w.qdata,(const std::uint16_t*)w.scales,s.packed,s.scales,errors);CUDA_CHECK(cudaGetLastError());std::vector<float>score(M);CUDA_CHECK(cudaMemcpyAsync(score.data(),errors,(std::size_t)M*sizeof(float),cudaMemcpyDeviceToHost,stream));CUDA_CHECK(cudaStreamSynchronize(stream));CUDA_CHECK(cudaFree(errors));if(correction_count()>0){if(rank_mode()>0){float*dn=nullptr;CUDA_CHECK(cudaMalloc(&dn,(std::size_t)M*sizeof(float)));down_column_norm<<<M,256,0,stream>>>((const std::int8_t*)down.qdata,(const std::uint16_t*)down.scales,dn);CUDA_CHECK(cudaGetLastError());std::vector<float>norm(M);CUDA_CHECK(cudaMemcpyAsync(norm.data(),dn,(std::size_t)M*sizeof(float),cudaMemcpyDeviceToHost,stream));CUDA_CHECK(cudaStreamSynchronize(stream));CUDA_CHECK(cudaFree(dn));for(int i=0;i<M;++i)score[i]=rank_mode()==1?score[i]*std::sqrt(norm[i]):norm[i];}std::vector<std::int32_t>rows(M);std::iota(rows.begin(),rows.end(),0);std::partial_sort(rows.begin(),rows.begin()+CORR_CAP,rows.end(),[&](int a,int b){return score[a]!=score[b]?score[a]>score[b]:a<b;});CUDA_CHECK(cudaMalloc(&s.corr_rows,(std::size_t)CORR_CAP*sizeof(std::int32_t)));CUDA_CHECK(cudaMalloc(&s.corr_codes,CORR_CODES));CUDA_CHECK(cudaMalloc(&s.corr_scales,CORR_SCALES));CUDA_CHECK(cudaMalloc(&s.exact_values,(std::size_t)2*CORR_CAP*sizeof(__nv_bfloat16)));CUDA_CHECK(cudaMemcpyAsync(s.corr_rows,rows.data(),(std::size_t)CORR_CAP*sizeof(std::int32_t),cudaMemcpyHostToDevice,stream));gather_corrections<<<CORR_CAP,256,0,stream>>>(s.corr_rows,(const std::int8_t*)w.qdata,(const std::uint16_t*)w.scales,s.corr_codes,s.corr_scales);CUDA_CHECK(cudaGetLastError());CUDA_CHECK(cudaStreamSynchronize(stream));}s.source=w.qdata;}
bool w8_mtp_gateup_b2_sm75_ready(const Weight&w) noexcept{return state().source==w.qdata&&state().packed;}
bool w8_mtp_gateup_b2_sm75_use(const Weight&w,int tokens) noexcept{int bit=tokens==1?1:(tokens==4?2:0);return bit&&(mode()&bit)&&w8_mtp_gateup_b2_sm75_ready(w);}
void w8_mtp_gateup_b2_sm75_launch(const Tensor&x,const Weight&w,Tensor&out,cudaStream_t stream){if(!w8_mtp_gateup_b2_sm75_ready(w)||x.dtype!=DType::BF16||x.ne[0]!=K||out.dtype!=DType::BF16||out.ne[0]!=M||out.ne[1]!=x.ne[1])throw std::invalid_argument("SM75 MTP W4/A8 gate/up launch requires prepared T1/T4 geometry");if(x.ne[1]==1)launch<1>(x,out,stream);else if(x.ne[1]==4)launch<4>(x,out,stream);else throw std::invalid_argument("SM75 MTP W4/A8 gate/up supports T1 or T4");}
} // namespace ninfer::ops::detail
